-- ==========================================================================
-- ملف استعلامات SQL: تصنيفات وأصناف سدانة المعتمدة (19 تصنيف و 77 صنف معتمد)
-- متطابقة 100% مع ملف: DOC-20261012-WA0002.xlsx (شيت: أصناف سدانة المعتمدة)
-- تاريخ التحديث: 2026-10-12
-- ==========================================================================

-- 1. حذف التصنيفات والأصناف السابقة لسدانة لضمان نظافة وتحديث البيانات
DELETE FROM categories WHERE type IN ('sedana_categories', 'sedana_items');

-- 2. إدراج تصنيفات سدانة الرئيسية (19 تصنيف معتمد)

-- 3. إدراج أصناف سدانة المعتمدة التابعة للتصنيفات (77 صنف معتمد)

-- 4. التحقق من العدد بعد الإدراج
SELECT type, COUNT(*) as total_count FROM categories WHERE type IN ('sedana_categories', 'sedana_items') GROUP BY type;
